package pl.zagranietyper.service;import pl.zagranietyper.model.*;
public final class FootballCompetitionProgressionNormalizer {public FootballCompetitionProgressionSnapshot normalize(ApiFootballCompetitionFixturesResponse r){var s=switch(r.status()){case SUCCESS->FootballCompetitionProgressionSnapshot.Status.COMPLETE;case EMPTY->FootballCompetitionProgressionSnapshot.Status.UNSUPPORTED_OR_EMPTY;case FETCH_FAILED->FootballCompetitionProgressionSnapshot.Status.FETCH_FAILED;case API_ERROR->FootballCompetitionProgressionSnapshot.Status.API_ERROR;case PARSE_ERROR->FootballCompetitionProgressionSnapshot.Status.PARSE_ERROR;};return new FootballCompetitionProgressionSnapshot(r.leagueId(),r.season(),s,r.rawJson(),r.errorMessage(),r.fetchedAt(),r.fixtures().stream().map(f->new FootballCompetitionProgressionSnapshot.Fixture(f.fixtureId(),f.round(),f.status(),f.kickoff(),f.homeId(),f.homeName(),f.homeWinner(),f.awayId(),f.awayName(),f.awayWinner(),f.goalsHome(),f.goalsAway(),f.ftHome(),f.ftAway(),f.etHome(),f.etAway(),f.penHome(),f.penAway())).toList());}}
